SELECT COUNT(*)
FROM plugin_data
WHERE plugin_id = #{pluginId} AND collection_name = #{collection} AND data_key = #{dataKey}

SELECT COUNT(*)
FROM plugin_data
WHERE plugin_id = #{pluginId}

SELECT data_json
FROM plugin_data
WHERE plugin_id = #{pluginId} AND collection_name = #{collection} AND data_key = #{dataKey}

SELECT JSON_ARRAYAGG(JSON_OBJECT('key', data_key, 'json', CAST(data_json AS JSON))) AS json_value
FROM (
  SELECT data_key, data_json
  FROM plugin_data
  WHERE plugin_id = #{pluginId} AND collection_name = #{collection}
  ORDER BY id
  LIMIT #{limit}
) limited_data
